<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('appointments.view');$pageTitle='Citas y reuniones';$status=(string)($_GET['status']??'');$where=[];$params=[];if($status!==''&&in_array($status,['scheduled','completed','cancelled','no_show'],true)){$where[]='a.status=?';$params[]=$status;}if(current_user()['role']!=='admin'){$where[]='(a.assigned_to=? OR a.created_by=?)';$params[]=(int)$_SESSION['user_id'];$params[]=(int)$_SESSION['user_id'];}$sql="SELECT a.*,c.company_name,CONCAT(p.first_name,' ',COALESCE(p.last_name,'')) contact_name,d.title deal_title,u.name assigned_name FROM appointments a LEFT JOIN clients c ON c.id=a.client_id LEFT JOIN contacts p ON p.id=a.contact_id LEFT JOIN deals d ON d.id=a.deal_id LEFT JOIN users u ON u.id=a.assigned_to".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY CASE WHEN a.start_at>=NOW() THEN 0 ELSE 1 END,a.start_at ASC";$st=db()->prepare($sql);$st->execute($params);$rows=$st->fetchAll();require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2>Agenda comercial</h2><span class="table-sub">Programa llamadas, reuniones y citas; usa Sócrates Meet para compartir tu enlace de reserva.</span></div><div class="actions"><a class="btn btn-secondary" href="https://www.socrates.la/meet" target="_blank" rel="noopener">ABRIR SÓCRATES MEET ↗</a><?php if(has_permission('appointments.manage')):?><a class="btn btn-primary" href="appointment_form.php">+ PROGRAMAR</a><?php endif;?></div></div><div class="panel-body"><form class="filters"><select name="status"><option value="">Todos los estados</option><?php foreach(['scheduled'=>'Programadas','completed'=>'Completadas','cancelled'=>'Canceladas','no_show'=>'No asistió']as$k=>$l):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$l?></option><?php endforeach;?></select><button class="btn btn-light btn-small">Filtrar</button></form></div><div class="table-wrap"><?php if(!$rows):?><div class="empty">No hay citas registradas.</div><?php else:?><table class="data-table"><thead><tr><th>Reunión</th><th>Fecha y hora</th><th>Cliente / contacto</th><th>Responsable</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><strong><?=e($r['title'])?></strong><span class="table-sub"><?=e($r['deal_title']?:'')?></span></td><td><?=e((new DateTimeImmutable($r['start_at']))->format('d/m/Y H:i'))?><?php if($r['end_at']):?><span class="table-sub">hasta <?=e((new DateTimeImmutable($r['end_at']))->format('H:i'))?></span><?php endif;?></td><td><?=e($r['company_name']?:'—')?><span class="table-sub"><?=e(trim((string)$r['contact_name']))?></span></td><td><?=e($r['assigned_name']?:'Sin asignar')?></td><td><span class="badge badge-<?=e($r['status']==='completed'?'green':($r['status']==='cancelled'?'gray':'blue'))?>"><?=e($r['status'])?></span></td><td><div class="actions"><?php if($r['meeting_url']):?><a class="btn btn-secondary btn-small" href="<?=e($r['meeting_url'])?>" target="_blank">Abrir reunión</a><?php endif;?><?php if(has_permission('appointments.manage')):?><a class="btn btn-light btn-small" href="appointment_form.php?id=<?=(int)$r['id']?>">Editar</a><a class="btn btn-light btn-small" href="appointment_send.php?id=<?=(int)$r['id']?>&channel=email">Email</a><a class="btn btn-light btn-small" href="appointment_send.php?id=<?=(int)$r['id']?>&channel=whatsapp">WhatsApp</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
